package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.protocol.packets.interface_.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.pages.InteractiveCustomUIPage;import com.hypixel.hytale.server.core.ui.builder.*;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.*;import java.util.*;
/** Two field tasks, native controls and server-checked local authority. */
final class FieldPage extends InteractiveCustomUIPage<StationPage.Action>{
 private String selected;private boolean expedition,rewards,rewardReveal;private int page,reward;private String mission="survey";private List<RescueService.Signal>rows=List.of();private LunarExpedition.Site site;
 FieldPage(PlayerRef p,boolean expedition,LunarExpedition.Site site){super(p,CustomPageLifetime.CanDismiss,StationPage.Action.CODEC);this.expedition=expedition;this.site=site;}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,RocketRegistry.Cell at,boolean expedition){
  var flight=s.getComponent(r,AstralReachPlugin.flightType);if(flight!=null&&flight.boarded&&!SpaceFlight.inOrbit(s,r)){AstralReachPlugin.message(p,"Use the receiver on foot or after reaching orbit.");return;}Observatory.end(s,r,p);
  var journal=FieldService.journal(s,r);var blueprint=at==null?null:BlueprintService.inspect(s,r,at);String id=at==null?"":NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at));if(id.equals("AR_ResearchArchive")||id.equals("AR_DamagedRelay"))journal.selectedMission="survey";
  var f=new FieldPage(p,expedition,blueprint!=null?blueprint.survey():at!=null&&expedition?FieldService.nearest(s,r):FieldService.site(s,r));f.mission=journal.selectedMission;f.reward=index(f.mission);
  if(at!=null){f.selected=RescueService.key(s,at);if(blueprint==null)FieldService.inspect(s,r,at,f.site);}RescueService.publish(s);RescueService.refreshSaved();s.getComponent(r,Player.getComponentType()).getPageManager().openCustomPage(r,s,f);
 }
 static int index(String mission){return mission.equals(BlueprintExpedition.Kind.LIFE_SUPPORT.id)?1:mission.equals(BlueprintExpedition.Kind.MOBILITY.id)?2:0;}
 static BlueprintExpedition.Kind kind(int index){return index==1?BlueprintExpedition.Kind.LIFE_SUPPORT:BlueprintExpedition.Kind.MOBILITY;}
 static String title(int index){return index==0?ExpeditionPerks.FUEL_TITLE:kind(index).reward;}
 static boolean earned(FieldJournal j,int index){return index==0?j.perks.contains(ExpeditionPerks.LOST_SURVEY):j.blueprints.contains(kind(index).id);}
 private BlueprintExpedition.Site blueprint(Store<EntityStore>s,Ref<EntityStore>r){var bp=BlueprintService.site(s,r,BlueprintExpedition.Kind.from(mission),site);site=bp.survey();FieldService.journal(s,r).selectedSite=site.id();return bp;}
 private void selectMission(Store<EntityStore>s,Ref<EntityStore>r,int index){mission=index==0?"survey":kind(index).id;reward=index;FieldService.journal(s,r).selectedMission=mission;if(index>0)blueprint(s,r);}
 private RescueService.Signal chosen(){return rows.stream().filter(e->e.key().equals(selected)).findFirst().orElse(null);}
 private void labels(Store<EntityStore>s,Ref<EntityStore>r,UICommandBuilder c){long now=System.currentTimeMillis();c.set("#Receiver.Visible",!rewardReveal);c.set("#RewardReveal.Visible",rewardReveal&&reward==0);c.set("#BlueprintReveal.Visible",rewardReveal&&reward>0);c.set("#Map.Disabled",!SpaceFlight.inOrbit(s,r));c.set("#Map.Visible",!rewards);c.set("#StopTracking.Visible",!rewards);rows=RescueService.signals(playerRef.getUuid());if(chosen()==null&&!rows.isEmpty())selected=rows.getFirst().key();var selectedSignal=chosen();page=Math.clamp(page,0,Math.max(0,(rows.size()-1)/5));c.set("#RescueBody.Visible",!expedition&&!rewards);c.set("#ExpeditionBody.Visible",expedition);c.set("#RewardsBody.Visible",rewards);c.set("#RescueSelected.Visible",!expedition&&!rewards);c.set("#ExpeditionSelected.Visible",expedition);c.set("#RewardsSelected.Visible",rewards);
  for(int i=0;i<5;i++){int n=page*5+i;boolean show=n<rows.size();c.set("#Row"+i+".Visible",show);if(show){var e=rows.get(n);c.set("#RowName"+i+".Text",e.name());c.set("#RowWorld"+i+".Text",body(e.world())+" · "+(e.active(now)?NativeUi.duration((e.expires()-now)/1000d):"Inactive"));c.set("#RowSelected"+i+".Visible",e.key().equals(selected));}}
  c.set("#Page.Text",(page+1)+" / "+Math.max(1,(rows.size()+4)/5));c.set("#Previous.Disabled",page==0);c.set("#Next.Disabled",(page+1)*5>=rows.size());
  c.set("#Name.Text",selectedSignal==null?"No invited signals":selectedSignal.name());c.set("#Condition.Text",selectedSignal==null?"Place a beacon and invite a rescuer":body(selectedSignal.world())+" · "+(selectedSignal.depth()>4?"Below surface · ":"")+selectedSignal.condition());c.set("#Oxygen.Text",selectedSignal==null||selectedSignal.oxygen()<0?"Unknown":NativeUi.duration(selectedSignal.oxygen()));c.set("#Battery.Text",selectedSignal==null?"--:--":NativeUi.duration(Math.max(0,selectedSignal.expires()-now)/1000d));c.set("#Coordinates.Text",selectedSignal==null?"":selectedSignal.at().x()+", "+selectedSignal.at().y()+", "+selectedSignal.at().z());c.set("#Depth.Text",selectedSignal==null?"":selectedSignal.depth()<0?"Depth unknown":"Depth · "+selectedSignal.depth()+"m");c.set("#Track.Disabled",selectedSignal==null||!selectedSignal.active(now));
  var at=selectedSignal!=null&&selectedSignal.world().equals(s.getExternalData().getWorld().getName())?selectedSignal.at():null;boolean own=false;RescueBeacon b=null;try{if(at!=null){b=RescueService.own(s,r,playerRef,at);own=true;}}catch(IllegalArgumentException ignored){}
  c.set("#Load.Disabled",!own||b.remaining(now)>0);c.set("#Toggle.Disabled",!own||b.remaining(now)==0);c.set("#Toggle.Text",b!=null&&b.enabled()?"Stop signal":"Broadcast");c.set("#Invite.Disabled",!own);c.set("#Revoke.Disabled",!own);c.set("#Guests.Text",b==null?"Stand beside your beacon to manage its battery and rescuers.":b.guests().isEmpty()?"Invited rescuers only · nobody invited yet":String.join(", ",b.guests().values()));c.set("#CellNote.Text","1 cell · 30 minutes · clock keeps running when stopped");int cells=0;var carried=s.getComponent(r,Player.getComponentType()).getInventory().getCombinedStorageHotbarBackpack();for(short slot=0;slot<carried.getCapacity();slot++){var item=carried.getItemStack(slot);if(item!=null&&!item.isEmpty()&&item.getItemId().equals("AR_BeaconCell"))cells+=item.getQuantity();}c.set("#CellCount.Text",Integer.toString(cells));
  var journal=FieldService.journal(s,r);boolean survey=mission.equals("survey");var bp=survey?null:blueprint(s,r);boolean discovered=survey?journal.discovered.contains(site.id()):journal.blueprintDiscoveries.contains(bp.id());int recovered=0;
  for(int i=0;i<2;i++)if(survey?journal.claimed.contains(FieldService.claimKey(site,i)):journal.blueprintRecords.contains(BlueprintExpedition.claim(bp,i)))recovered++;
  int missionIndex=index(mission);for(int i=0;i<3;i++)c.set("#MissionSelected"+i+".Visible",i==missionIndex);
  c.set("#Relay.Text",survey?"Track surface relay":"Track first outpost");c.set("#Shelter.Text",survey?"Track lost shelter":"Track second outpost");c.set("#Escape.Visible",survey);c.set("#Shelter.Disabled",!discovered);c.set("#Escape.Disabled",!discovered);c.set("#Other.Text",survey?"Next survey site":"Next mission site");
  c.set("#StoryTitle.Text",survey?"THE LOST SURVEY SHELTER":bp.kind().title.toUpperCase(java.util.Locale.ROOT));
  c.set("#Story.Text",survey?(discovered?"RELAY LOG · Pressure lost during the seismic survey. Follow the copper trail posts from the northern skylight to our shelter. Two terminals hold the survey record and evacuation log. The shelter has no breathable air.":"A damaged relay stands beside a collapsed skylight on Lune. Inspect it to find the survey team's trail. Bring a full suit, spare oxygen, a light and a way home."):missionIndex==1?"Follow the life-support team's pressure trials. Recover the compressor study at the first outpost and the regulator calibration at the second. Their twin-cylinder design stores forty minutes of oxygen. Both outposts are unpressurised.":"Recover the surface mobility team's chassis trial and battery-controller record from two field outposts. Their two-seat electric rover makes longer surface journeys possible. The rover has no pressurised cabin: keep your suit and oxygen supply.");
  c.set("#Progress.Text",(survey?"Archives recovered":"Field records recovered")+" · "+recovered+" / 2");c.set("#Salvage.Text",survey?"Survey: 2 titanium ingots + 2 frame plates\nEvacuation: 4 frame plates + 1 flight computer":"Reward: permanent recipe knowledge, with no free equipment.\nGather crafting materials after unlocking.");
  int available=survey?FieldService.recoverable(s,r,site):BlueprintService.recoverable(s,r,bp);boolean claimed=available>=0&&(survey?journal.claimed.contains(FieldService.claimKey(site,available)):journal.blueprintRecords.contains(BlueprintExpedition.claim(bp,available)));c.set("#Recover.Disabled",available<0||claimed);c.set("#Recover.Text",survey?"Recover data and salvage":"Recover field record");var location=survey?site.relay():bp.record(0);c.set("#Site.Text",(survey?"Relay":"First outpost")+" · "+location.x()+", "+location.z());
  boolean missionEarned=earned(journal,missionIndex);c.set("#PreviewState.Text",missionEarned?"PERMANENT REWARD · UNLOCKED":survey?"PERMANENT EXPEDITION REWARD":"PERMANENT RECIPE BLUEPRINT");c.set("#PreviewName.Text",title(missionIndex));c.set("#PreviewValue.Text",survey?"-5%":missionIndex==1?"40 min":"2");c.set("#PreviewEffect.Text",survey?"Rocket fuel usage":missionIndex==1?"Normal breathing":"Seats · electric rover");c.set("#PreviewHint.Text",missionEarned?(survey?"Always active · 450 fuel saved per round trip":"Recipe learned · materials still required"):"Recover both records at this site to unlock");
  for(int i=0;i<3;i++){c.set("#PreviewArt"+i+".Visible",missionIndex==i);c.set("#RewardSelected"+i+".Visible",reward==i);c.set("#RewardRowState"+i+".Text",earned(journal,i)?"UNLOCKED":"LOCKED");c.set("#DetailArt"+i+".Visible",reward==i);c.set("#RevealArt"+i+".Visible",reward==i);}
  int count=0;for(int i=0;i<3;i++)if(earned(journal,i))count++;boolean unlocked=earned(journal,reward);c.set("#RewardCount.Text",count+" PERMANENT REWARD"+(count==1?"":"S")+" EARNED");c.set("#ReviewReward.Visible",rewards&&unlocked);c.set("#ReviewReward.Text",reward==0?"View achievement":"View blueprint");c.set("#RewardTitle.Text",title(reward));c.set("#RewardState.Text",unlocked?(reward==0?"PERMANENT · ALWAYS ACTIVE":"PERMANENT · RECIPE LEARNED"):"PERMANENT · NOT YET UNLOCKED");c.set("#FuelDetail.Visible",reward==0);c.set("#BlueprintDetail.Visible",reward>0);
  c.set("#RewardOrigin.Text",reward==0?(unlocked?"Earned by recovering both archives at one Lost Survey shelter.":"Recover both archives at one Lost Survey shelter to permanently unlock this reward."):"Craft at "+(reward==1?"Suit Workbench / Survey equipment. Fill the empty tank at an Oxygen Collector.":"Astral Assembly Bench / Station equipment. Power it with Beacon Cells."));c.set("#RewardNote.Text",unlocked?(reward==0?"Unlocked once per player. Repeat sites do not stack.":"Recipe knowledge is permanent; crafting still uses materials."):"Locked preview · Complete both records at one site.");
  if(reward>0){var k=kind(reward);var recipes=com.hypixel.hytale.builtin.crafting.CraftingPlugin.getBenchRecipes(com.hypixel.hytale.protocol.BenchType.Crafting,reward==1?"AstralSuit":"AstralAssembly");var recipe=recipes.stream().filter(x->x.getPrimaryOutput()!=null&&k.item.equals(x.getPrimaryOutput().getItemId())).findFirst().orElseThrow(()->new IllegalArgumentException("Native blueprint recipe unavailable"));var inputs=recipe.getInput();for(int i=0;i<6;i++){c.set("#Ingredient"+i+".Visible",i<inputs.length);if(i<inputs.length){c.set("#IngredientIcon"+i+".ItemId",inputs[i].getItemId());c.set("#IngredientCount"+i+".Text",Integer.toString(inputs[i].getQuantity()));}}c.set("#RecipeTitle.Text",title(reward));c.set("#RecipeDescription.Text",reward==1?"Build an empty twin-cylinder tank, then fill it using the collector's normal fuel supply.":"Build a two-seat rover kit. Each Beacon Cell supplies fifteen minutes of moving power.");}
  c.set("#BlueprintTitle.Text",title(reward));c.set("#BlueprintHero1.Visible",reward==1);c.set("#BlueprintHero2.Visible",reward==2);c.set("#BlueprintCapability.Text",reward==1?"Stay outside longer between refills.":"Explore farther across Lune.");c.set("#BlueprintRecipeName.Text",title(reward));c.set("#BlueprintRecipeIcon.ItemId",reward==1?"AR_EmptyLargeOxygenCanister":"AR_LunarRover");c.set("#RevealHeading.Text",reward==0?"EXPEDITION COMPLETE":"BLUEPRINT UNLOCKED");c.set("#RevealMission.Text",reward==0?"The Lost Survey Shelter":kind(reward).title);c.set("#RevealTag.Text",reward==0?"PERMANENT REWARD UNLOCKED":"PERMANENT EXPEDITION RECIPE");c.set("#RevealTitle.Text",title(reward));c.set("#RevealFuelDetail.Visible",reward==0);c.set("#RevealBlueprintDetail.Visible",reward>0);c.set("#RevealCapability.Visible",reward>0);c.set("#RevealRecipeIcon.ItemId",reward==1?"AR_EmptyLargeOxygenCanister":"AR_LunarRover");c.set("#RevealCapability.Text",reward==1?"Stay outside longer between refills.":"Explore farther across Lune.");c.set("#RevealRecipeName.Text",title(reward));c.set("#RevealNote.Text",reward==0?"Always active · No equipment required":"Permanently added to your recipes");c.set("#RewardContinue.Text",reward==0?"Continue":"View recipe");
 }

 static String body(String world){return switch(world){case "AstralLune"->"Lune";case "AstralOrbit"->"Orbis orbit";default->"Orbis";};}
 @Override public void build(Ref<EntityStore>r,UICommandBuilder c,UIEventBuilder e,Store<EntityStore>s){c.append("Pages/AstralReach/FieldReceiver.ui");labels(s,r,c);for(String a:List.of("Rescue","Expedition","Rewards","RewardContinue","ReviewReward","Previous","Next","Track","Load","Toggle","Relay","Shelter","Escape","Recover","Other","StopTracking","Close","Map"))e.addEventBinding(CustomUIEventBindingType.Activating,"#"+a,EventData.of("Action",a),false);for(String a:List.of("Invite","Revoke"))e.addEventBinding(CustomUIEventBindingType.Activating,"#"+a,EventData.of("Action",a).append("@Name","#InviteName.Value"),false);for(int i=0;i<3;i++){e.addEventBinding(CustomUIEventBindingType.Activating,"#Mission"+i,EventData.of("Action","Mission"+i),false);e.addEventBinding(CustomUIEventBindingType.Activating,"#RewardEntry"+i,EventData.of("Action","RewardEntry"+i),false);}for(int i=0;i<5;i++)e.addEventBinding(CustomUIEventBindingType.Activating,"#Row"+i,EventData.of("Action","Row"+i),false);e.addEventBinding(CustomUIEventBindingType.Activating,"#BlueprintContinue",EventData.of("Action","RewardContinue"),false);NativeUi.cue(s,playerRef);}
 void refresh(Store<EntityStore>s,Ref<EntityStore>r){var c=new UICommandBuilder();labels(s,r,c);sendUpdate(c,false);}
 @Override public void handleDataEvent(Ref<EntityStore>r,Store<EntityStore>s,StationPage.Action a){s.getExternalData().getWorld().execute(()->{if(!r.isValid()||r.getStore()!=s||s.getComponent(r,Player.getComponentType()).getPageManager().getCustomPage()!=this)return;try{switch(a.action){case "Close"->{close();return;}case "Map"->{if(SpaceFlight.inOrbit(s,r)){OrbitalMapPage.open(s,r,playerRef);return;}throw new IllegalArgumentException("Launch to orbit before choosing a destination.");}case "Rescue"->{expedition=false;rewards=false;}case "Expedition"->{expedition=true;rewards=false;}case "Rewards"->{expedition=false;rewards=true;}case "ReviewReward"->{if(!earned(FieldService.journal(s,r),reward))throw new IllegalArgumentException("Complete the expedition to view your achievement.");rewardReveal=true;}case "RewardContinue"->{rewardReveal=false;expedition=false;rewards=true;}case "Previous"->page--;case "Next"->page++;case "StopTracking"->FieldService.stop(s,r,playerRef);case "Other"->{site=new LunarExpedition.Site(site.seed(),site.channel(),site.start()-1536);if(!mission.equals("survey")){var k=BlueprintExpedition.Kind.from(mission);for(int i=0;i<64&&!BlueprintExpedition.at(site,k).valid();i++)site=new LunarExpedition.Site(site.seed(),site.channel(),site.start()-1536);if(!BlueprintExpedition.at(site,k).valid())throw new IllegalArgumentException("No suitable outpost found here; try another region.");}FieldService.journal(s,r).selectedSite=site.id();}
case "Relay"->{if(mission.equals("survey"))FieldService.track(playerRef,site.relay(),"Damaged survey relay");else{var bp=blueprint(s,r);FieldService.track(playerRef,bp.record(0),bp.kind().title+" · first outpost");}}
case "Shelter","Escape"->{if(mission.equals("survey")){if(!FieldService.journal(s,r).discovered.contains(site.id()))throw new IllegalArgumentException("Inspect the original relay or an archive to recover this trail.");FieldService.track(playerRef,a.action.equals("Shelter")?site.archive(0):site.entrance(true),a.action.equals("Shelter")?"Lost survey shelter":"Southern skylight");}else{var bp=blueprint(s,r);if(!FieldService.journal(s,r).blueprintDiscoveries.contains(bp.id()))throw new IllegalArgumentException("Inspect the first outpost to recover this route.");FieldService.track(playerRef,bp.record(1),bp.kind().title+" · second outpost");}}
case "Recover"->{boolean unlocked;if(mission.equals("survey")){boolean before=earned(FieldService.journal(s,r),0);FieldService.recover(s,r,playerRef,site);unlocked=!before&&earned(FieldService.journal(s,r),0);}else unlocked=BlueprintService.recover(s,r,playerRef,blueprint(s,r));if(unlocked){reward=index(mission);rewardReveal=true;expedition=false;rewards=true;}}
case "Track"->{var signal=RescueService.find(selected,playerRef.getUuid());if(signal==null)throw new IllegalArgumentException("Signal no longer available.");FieldService.track(playerRef,signal);}case "Load","Toggle","Invite","Revoke"->{var signal=RescueService.find(selected,playerRef.getUuid());if(signal==null||!signal.world().equals(s.getExternalData().getWorld().getName()))throw new IllegalArgumentException("Stand beside your own beacon.");RescueService.action(s,r,playerRef,signal.at(),a.action,a.name);}default->{if(a.action.matches("Mission[0-2]")){selectMission(s,r,Integer.parseInt(a.action.substring(7)));expedition=true;rewards=false;}else if(a.action.matches("RewardEntry[0-2]")){reward=Integer.parseInt(a.action.substring(11));expedition=false;rewards=true;}else if(a.action.matches("Row[0-4]")){int i=page*5+Integer.parseInt(a.action.substring(3));if(i<rows.size())selected=rows.get(i).key();}}}refresh(s,r);}catch(IllegalArgumentException ex){AstralReachPlugin.message(playerRef,ex.getMessage());refresh(s,r);}});}
}
